package com.djibtout.backend.controller;import com.djibtout.backend.entity.*;import com.djibtout.backend.repository.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/admin/category-attributes") public class AdminCategoryAttributeController{private final CategoryAttributeRepository attributes;private final CategoryRepository categories;private final UserRepository users;public AdminCategoryAttributeController(CategoryAttributeRepository a,CategoryRepository c,UserRepository u){attributes=a;categories=c;users=u;}private boolean admin(Authentication a){return a!=null&&users.findByEmail(a.getName()).map(u->u.getRole()==Role.ADMIN).orElse(false);}@GetMapping public ResponseEntity<?> list(Authentication a,@RequestParam Long categoryId){return admin(a)?ResponseEntity.ok(attributes.findByCategoryId(categoryId)):ResponseEntity.status(403).build();}@PostMapping public ResponseEntity<?> create(Authentication a,@Valid @RequestBody Input i){if(!admin(a))return ResponseEntity.status(403).build();CategoryAttribute x=new CategoryAttribute();return save(x,i);}@PutMapping("/{id}") public ResponseEntity<?> update(Authentication a,@PathVariable Long id,@Valid @RequestBody Input i){if(!admin(a))return ResponseEntity.status(403).build();CategoryAttribute x=attributes.findById(id).orElse(null);return x==null?ResponseEntity.notFound().build():save(x,i);}@DeleteMapping("/{id}") public ResponseEntity<?> delete(Authentication a,@PathVariable Long id){if(!admin(a))return ResponseEntity.status(403).build();attributes.deleteById(id);return ResponseEntity.noContent().build();}private ResponseEntity<?> save(CategoryAttribute x,Input i){Category c=categories.findById(i.categoryId()).orElse(null);if(c==null)return ResponseEntity.badRequest().body("Catégorie inconnue.");x.setCategory(c);x.setName(i.name().trim());x.setRequired(i.required());x.setValues(i.values().stream().filter(v->v!=null&&!v.isBlank()).map(String::trim).distinct().toList());return ResponseEntity.ok(attributes.save(x));}public record Input(@NotNull Long categoryId,@NotBlank @Size(max=80) String name,boolean required,@Size(max=100) List<@Size(max=100) String> values){}}
